/** ILLUSIONCULUM SAGA — the scroll suit-up's change of form (2026-10-23).
 *
 * The armour itself is generated by the Rexonance nanite engine (owner,
 * 2026-10-23: 「ナノマシンで生成された装甲をしてから装着する方式」): the plates
 * are formed off the body from nanite cells, then fly in and lock onto the
 * undersuit. This module draws only what follows the seal, the chain of
 * forms (the engine's opt-in `formChange`, called per change):
 *
 * - リアクター・モア: the body is the same in both sheets, so the change is
 *   the two orbs — each rises out of the shoulder line, arcs out to its
 *   seat and resolves there out of its own projection of light;
 * - ウルトラ: the ウルトラ figure takes the body from the reactor out, inside a
 *   circle that grows over the change, its front a thin dim crimson ring
 *   (the art carries the colour; never a flash of red light).
 *
 * 2026-11 prism pass: every change now reads as light through a crystal —
 * the ウルトラ circle's front is a refracting lens (a thin band of the
 * incoming figure magnified just outside the edge, three dispersed hairlines
 * ice / pink / gold around the dim crimson ring, a few prism glints on it);
 * the projections are flat ice and pink silhouettes of the incoming figure
 * (made once per figure, at half size) that part and close; each orb leaves a
 * short comet of itself and lands in a ring of dispersed light.
 *
 * Closed-form in `u`, allocation-free in a frame (the orb sprites and the two
 * projection silhouettes are made once per change, never in a frame), no
 * shadows or filters (Android).
 */

import type { RexonanceAssemblyFormChange } from "./rexonance-resonance.js";

const ORB_TONES = ["rgb(166 230 255)", "rgb(169 131 255)"] as const;
/** The prism's three dispersed hairlines: ice, pink, gold. */
const PRISM_TONES = ["rgb(166 230 255)", "rgb(255 143 210)", "rgb(255 225 163)"] as const;
const FROST_HI = "rgb(220 246 255)";
const CRIMSON_FRONT = "rgb(184 31 58)";
const CRIMSON_EMBER = "rgb(233 158 102)";
const GOLDEN_ANGLE = 2.399963229728653;
const GLINTS = 15;
const FROST_FACETS = 16;
const ARC_STEPS = 10;
const TRAIL = 3;
const clamp01 = (value: number) => (value < 0 ? 0 : value > 1 ? 1 : value);
const smooth = (u: number) => u * u * (3 - 2 * u);

export type IllusionculumOrb = readonly [number, number, number];

export type IllusionculumFormChangeOptions = {
  size: { readonly width: number; readonly height: number };
  core: readonly [number, number];
  /** The two リアクター・モア: [x, y, radius] (figure px). */
  orbs: readonly IllusionculumOrb[];
  /** The forms that carry the orbs, and the ウルトラ forms (chain keys). */
  orbForms: readonly string[];
  ultraForms: readonly string[];
};

export function createIllusionculumFormChange(
  options: IllusionculumFormChangeOptions,
): RexonanceAssemblyFormChange {
  const { width: W, height: H } = options.size;
  const core = options.core;
  let orbGhosts: HTMLCanvasElement[] | null = null;
  // The projections: ice and pink silhouettes of the incoming figure, half
  // size, made once per figure (the first frame that wants them).
  const TW = Math.max(1, Math.round(W / 2));
  const TH = Math.max(1, Math.round(H / 2));
  const silhouettes: (HTMLCanvasElement | null)[] = [null, null];
  let silhouetteOf: CanvasImageSource | null = null;
  const prepareSilhouettes = (document: Document, figure: CanvasImageSource) => {
    if (silhouetteOf === figure) return;
    silhouetteOf = figure;
    for (let k = 0; k < 2; k += 1) {
      const canvas = (silhouettes[k] ??= document.createElement("canvas"));
      if (canvas.width !== TW) canvas.width = TW;
      if (canvas.height !== TH) canvas.height = TH;
      const gc = canvas.getContext("2d");
      if (!gc) continue;
      gc.globalCompositeOperation = "copy";
      gc.drawImage(figure, 0, 0, TW, TH);
      gc.globalCompositeOperation = "source-in";
      gc.fillStyle = PRISM_TONES[k];
      gc.fillRect(0, 0, TW, TH);
      gc.globalCompositeOperation = "source-over";
    }
  };
  // Where an orb is at eased progress `e`: out of the shoulder line, in
  // toward the neck and low, up and out along an arc to the seat.
  let orbX = 0;
  let orbY = 0;
  const placeOrb = (ox: number, oy: number, r: number, e: number) => {
    const fromX = ox + (ox < W / 2 ? 1 : -1) * r * 1.1;
    const fromY = oy + r * 1.9;
    const arc = Math.sin(Math.PI * Math.min(1, e * 1.1)) * r * 0.5;
    orbX = fromX + (ox - fromX) * e;
    orbY = fromY + (oy - fromY) * e - arc;
  };
  return {
    form(context, from, to, fromKey, toKey, u, _tone, calm) {
      context.globalAlpha = 1;
      context.globalCompositeOperation = "source-over";
      const e = smooth(u);
      const orbsIn = options.orbForms.includes(toKey) && !options.orbForms.includes(fromKey);
      const ultraIn = options.ultraForms.includes(toKey) && !options.ultraForms.includes(fromKey);
      if (ultraIn) {
        // ウルトラ from the reactor out: the ウルトラ figure inside a circle
        // that grows over the change, its front a lens (a refracting band,
        // dispersed hairlines, a few glints) around a thin dim crimson ring
        // (the art itself carries the colour: no flash of red light).
        context.drawImage(from, 0, 0, W, H);
        const [cx, cy] = core;
        const reach = Math.hypot(Math.max(cx, W - cx), Math.max(cy, H - cy));
        const radius = Math.max(0.5, reach * e);
        const pulse = Math.sin(Math.PI * u);
        // Its projections first: ice and pink silhouettes, parted and closing.
        if (!calm && u < 0.7) {
          prepareSilhouettes(context.canvas.ownerDocument, to);
          const left = silhouettes[0];
          const right = silhouettes[1];
          const shift = (1 - e) * W * 0.06;
          const fade = 1 - u / 0.7;
          context.globalCompositeOperation = "lighter";
          context.globalAlpha = 0.1 * fade;
          if (left) context.drawImage(left, -shift * 1.25, 0, W, H);
          if (right) context.drawImage(right, shift * 1.25, 0, W, H);
          context.globalAlpha = 0.16 * fade;
          context.drawImage(to, -shift, 0, W, H);
          context.drawImage(to, shift, 0, W, H);
          context.globalCompositeOperation = "source-over";
        }
        context.save();
        context.beginPath();
        context.arc(cx, cy, radius, 0, Math.PI * 2);
        context.clip();
        context.clearRect(0, 0, W, H);
        context.globalAlpha = 1;
        context.drawImage(to, 0, 0, W, H);
        context.restore();
        if (u > 0 && u < 1) {
          if (!calm) {
            // The lens: the figure magnified a little, in a band just
            // outside the edge only.
            const band = 8 + W * 0.03 * pulse;
            const zoom = 1 + 0.022 * pulse;
            context.save();
            context.beginPath();
            context.arc(cx, cy, radius + band, 0, Math.PI * 2);
            context.moveTo(cx + radius, cy);
            context.arc(cx, cy, radius, 0, Math.PI * 2, true);
            context.clip();
            context.globalAlpha = 0.34 * pulse;
            context.drawImage(to, cx - cx * zoom, cy - cy * zoom, W * zoom, H * zoom);
            context.restore();
            // Crimson-frost erosion contrast: outer crystalline frost facets vs inner crimson-gold rim.
            context.globalCompositeOperation = "lighter";
            // 1. Retreating ice-crystal frost crown just ahead of the crimson wave front.
            context.strokeStyle = FROST_HI;
            context.lineWidth = 1.15;
            context.globalAlpha = 0.42 * pulse;
            context.beginPath();
            for (let f = 0; f < FROST_FACETS; f += 1) {
              const a = (f / FROST_FACETS) * Math.PI * 2 - e * 0.85;
              const spread = 0.055 + ((f * 3) % 4) * 0.012;
              const rIn = radius + 2.5;
              const rTip = radius + 10 + ((f * 5) % 4) * 3.2 * pulse;
              context.moveTo(cx + Math.cos(a - spread) * rIn, cy + Math.sin(a - spread) * rIn);
              context.lineTo(cx + Math.cos(a) * rTip, cy + Math.sin(a) * rTip);
              context.lineTo(cx + Math.cos(a + spread) * rIn, cy + Math.sin(a + spread) * rIn);
            }
            context.stroke();
            // 2. Dispersed prism hairlines: ice outside, pink mid, warm gold hugging the erosion front.
            context.lineWidth = 1.3;
            context.globalAlpha = 0.38 * pulse;
            for (let t = 0; t < 3; t += 1) {
              context.strokeStyle = PRISM_TONES[t];
              context.beginPath();
              context.arc(
                cx,
                cy,
                Math.max(0.5, radius + (1 - t) * (3.2 + 3.6 * pulse)),
                0,
                Math.PI * 2,
              );
              context.stroke();
            }
            // 3. Inner crimson-ember harmonic ring just inside the advancing wave.
            if (radius > 8) {
              context.strokeStyle = CRIMSON_EMBER;
              context.lineWidth = 1.2;
              context.globalAlpha = 0.34 * pulse;
              context.beginPath();
              context.arc(cx, cy, Math.max(0.5, radius - 3.5 - 2 * pulse), 0, Math.PI * 2);
              context.stroke();
            }
            // 4. Glints on the front, ice / pink / gold in turn.
            context.lineWidth = 1.5;
            context.globalAlpha = 0.52 * pulse;
            for (let t = 0; t < 3; t += 1) {
              context.strokeStyle = PRISM_TONES[t];
              context.beginPath();
              for (let k = t; k < GLINTS; k += 3) {
                const angle = k * GOLDEN_ANGLE + e * 1.6;
                const cos = Math.cos(angle);
                const sin = Math.sin(angle);
                const inner = Math.max(0, radius - 4);
                const outer = radius + 8 + ((k * 7) % 5) * 3.2 * pulse;
                context.moveTo(cx + cos * inner, cy + sin * inner);
                context.lineTo(cx + cos * outer, cy + sin * outer);
              }
              context.stroke();
            }
            context.globalCompositeOperation = "source-over";
          }
          context.globalAlpha = 0.54 * pulse;
          context.strokeStyle = CRIMSON_FRONT;
          context.lineWidth = 2.2;
          context.beginPath();
          context.arc(cx, cy, radius, 0, Math.PI * 2);
          context.stroke();
          context.globalAlpha = 1;
        }
        return true;
      }
      if (orbsIn) {
        // The body is the same in both sheets: the change is the orbs.
        context.drawImage(from, 0, 0, W, H);
        orbGhosts ??= options.orbs.map(([, , r]) => {
          const canvas = context.canvas.ownerDocument.createElement("canvas");
          canvas.width = canvas.height = Math.ceil(r * 2);
          return canvas;
        });
        const arrive = smooth(clamp01(u * 1.8));
        for (let k = 0; k < options.orbs.length; k += 1) {
          const [ox, oy, r] = options.orbs[k];
          placeOrb(ox, oy, r, e);
          const x = orbX;
          const y = orbY;
          const scale = 0.42 + 0.58 * e;
          const size = r * 2 * scale;
          // Multi-wavelength Reactor More orbital trajectory arcs & seat reticle.
          if (!calm && u > 0.02 && u < 0.96) {
            const arcFade = Math.sin(Math.PI * clamp01(u / 0.96));
            context.globalCompositeOperation = "lighter";
            for (let t = 0; t < 3; t += 1) {
              const offset = (t - 1) * 3.2 * (1 - e * 0.6);
              context.strokeStyle = PRISM_TONES[t];
              context.lineWidth = t === 0 ? 1.6 : 1.1;
              context.globalAlpha = (t === 0 ? 0.44 : 0.28) * arcFade;
              context.beginPath();
              const sStart = Math.max(0, e - 0.58);
              for (let step = 0; step <= ARC_STEPS; step += 1) {
                const sAt = sStart + ((e - sStart) * step) / ARC_STEPS;
                placeOrb(ox, oy, r, sAt);
                const pxArc = orbX + offset;
                const pyArc = orbY - Math.abs(offset) * 0.45;
                if (step === 0) context.moveTo(pxArc, pyArc);
                else context.lineTo(pxArc, pyArc);
              }
              context.stroke();
            }
            // Pre-lock diamond phase reticle tightening on the target seat.
            if (u < 0.78) {
              const lockFade = Math.sin(Math.PI * clamp01(u / 0.78));
              const dR = r * (0.62 - 0.24 * clamp01(u / 0.78));
              const spin = (k === 0 ? 1 : -1) * e * 1.4;
              context.strokeStyle = PRISM_TONES[k === 0 ? 0 : 2];
              context.lineWidth = 1.15;
              context.globalAlpha = 0.38 * lockFade;
              context.beginPath();
              for (let c = 0; c < 4; c += 1) {
                const a = spin + (c * Math.PI) / 2;
                const vx = ox + Math.cos(a) * dR;
                const vy = oy + Math.sin(a) * dR;
                if (c === 0) context.moveTo(vx, vy);
                else context.lineTo(vx, vy);
              }
              context.closePath();
              context.stroke();
            }
            context.globalCompositeOperation = "source-over";
          }
          // Its projection, ahead of it at the seat, fading as it lands.
          const ghost = orbGhosts[k];
          const gc = ghost.getContext("2d");
          if (gc && !calm) {
            gc.globalCompositeOperation = "copy";
            gc.drawImage(to, ox - r, oy - r, r * 2, r * 2, 0, 0, r * 2, r * 2);
            gc.globalCompositeOperation = "source-in";
            gc.fillStyle = ORB_TONES[k % 2];
            gc.fillRect(0, 0, r * 2, r * 2);
            context.globalCompositeOperation = "lighter";
            context.globalAlpha = 0.32 * Math.sin(Math.PI * Math.min(1, u * 1.15));
            context.drawImage(ghost, ox - r, oy - r, r * 2, r * 2);
            // A short comet of the orb itself, each step a little behind.
            for (let t = 1; t <= TRAIL; t += 1) {
              const behind = smooth(clamp01(u - t * 0.05));
              placeOrb(ox, oy, r, behind);
              const trail = r * 2 * (0.42 + 0.58 * behind) * (1 - t * 0.09);
              context.globalAlpha = (0.3 / t) * arrive * (1 - u * u * u);
              context.drawImage(
                ghost,
                0,
                0,
                r * 2,
                r * 2,
                orbX - trail / 2,
                orbY - trail / 2,
                trail,
                trail,
              );
            }
            context.globalCompositeOperation = "source-over";
          }
          context.globalAlpha = arrive;
          context.drawImage(
            to,
            ox - r,
            oy - r,
            r * 2,
            r * 2,
            x - size / 2,
            y - size / 2,
            size,
            size,
          );
          // Landing: dispersed diffraction rings & radial optical glints opening off the seat.
          if (!calm && u > 0.66 && u < 1) {
            const open = (u - 0.66) / 0.34;
            const decay = (1 - open) * (1 - open);
            context.globalCompositeOperation = "lighter";
            context.lineWidth = 1.5;
            context.globalAlpha = 0.48 * decay;
            for (let t = 0; t < 3; t += 1) {
              context.strokeStyle = PRISM_TONES[t];
              context.beginPath();
              context.arc(ox, oy, r * (1.02 + 0.88 * open + t * 0.09), 0, Math.PI * 2);
              context.stroke();
            }
            context.strokeStyle = FROST_HI;
            context.lineWidth = 1.25;
            context.globalAlpha = 0.52 * decay;
            context.beginPath();
            for (let g = 0; g < 8; g += 1) {
              const a = (g * Math.PI) / 4 + (k === 0 ? 0.2 : -0.2);
              const r0 = r * (0.94 + 0.55 * open);
              const r1 = r0 + r * 0.26 * (1 - open);
              context.moveTo(ox + Math.cos(a) * r0, oy + Math.sin(a) * r0);
              context.lineTo(ox + Math.cos(a) * r1, oy + Math.sin(a) * r1);
            }
            context.stroke();
            context.globalCompositeOperation = "source-over";
          }
        }
        context.globalAlpha = 1;
        return true;
      }
      // Any other change: the next figure resolves over the last, through a
      // faint ice projection that parts from it and closes.
      context.drawImage(from, 0, 0, W, H);
      if (!calm && u > 0 && u < 1) {
        prepareSilhouettes(context.canvas.ownerDocument, to);
        const left = silhouettes[0];
        if (left) {
          context.globalCompositeOperation = "lighter";
          context.globalAlpha = 0.12 * Math.sin(Math.PI * u);
          context.drawImage(left, -(1 - e) * W * 0.025, 0, W, H);
          context.globalCompositeOperation = "source-over";
        }
      }
      context.globalAlpha = e;
      context.drawImage(to, 0, 0, W, H);
      context.globalAlpha = 1;
      return true;
    },
  };
}
